<script setup lang="ts">
import { EmptyState, PageHeader, StatusBadge } from '#fsd/shared/ui'
type Notification = { id: string; title: string; body: string; href: string; readAt: string | null; createdAt: string }
const { data: items, refresh, status } = await useAsyncData('notifications', () => $fetch<Notification[]>('/api/notifications'))
const formatTime = (value: string) => new Intl.DateTimeFormat('ru-RU', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value))
async function read(item: Notification) { if (!item.readAt) await $fetch(`/api/notifications/${item.id}/read`, { method: 'POST' }); await refresh(); await navigateTo(item.href) }
</script>
<template><section class="page-wrap space-y-6"><PageHeader title="Уведомления" description="Назначения, изменения заездов и проблемы по объектам." /><div v-if="status === 'pending'" class="grid gap-3"><USkeleton v-for="item in 4" :key="item" class="h-24 rounded-2xl" /></div><div v-else-if="items?.length" class="surface divide-y divide-[var(--color-line)] px-4 sm:px-6"><button v-for="item in items" :key="item.id" type="button" class="flex min-h-24 w-full items-start gap-4 rounded-xl py-4 text-left transition-[background-color,scale] duration-150 hover:bg-[#f5f8f6] active:scale-[.99]" @click="read(item)"><span class="mt-1 size-2 shrink-0 rounded-full" :class="item.readAt ? 'bg-transparent' : 'bg-[var(--color-primary)]'" /><span class="min-w-0 flex-1"><span class="flex flex-wrap items-center gap-2"><strong>{{ item.title }}</strong><StatusBadge v-if="!item.readAt" label="Новое" tone="success" /></span><span class="mt-1 block text-sm leading-6 text-[var(--color-muted)]">{{ item.body }}</span><span class="mt-2 block text-xs text-[var(--color-muted)]">{{ formatTime(item.createdAt) }}</span></span><UIcon name="i-lucide-chevron-right" class="mt-1 size-5 shrink-0 text-[var(--color-muted)]" /></button></div><EmptyState v-else icon="i-lucide-bell" title="Уведомлений пока нет" description="Здесь появятся важные события по заездам и работам." /></section></template>
